  5→function getAllowedOrigin(req: Request): string {
  6→  const origin = req.headers.get("origin") || "";
  7→  const allowed = ["https://rankora.co", "https://www.rankora.co", "http://localhost:8080", "http://localhost:5173"];
  8→  return allowed.includes(origin) ? origin : "https://rankora.co";
  9→}
