 26→/** Send an email via Resend API */
 27→async function sendViaResend(
 28→  apiKey: string,
 29→  from: { email: string; name: string },
 30→  to: string,
 31→  subject: string,
 32→  htmlContent: string
 33→): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
 34→  const res = await fetch("https://api.resend.com/emails", {
 35→    method: "POST",
 36→    headers: {
 37→      "Authorization": `Bearer ${apiKey}`,
 38→      "Content-Type": "application/json",
 39→    },
 40→    body: JSON.stringify({
 41→      from: `${from.name} <${from.email}>`,
 42→      to: [to],
 43→      subject,
 44→      html: htmlContent,
 45→    }),
 46→  });
 47→
 48→  const body = await res.text();
 49→  let errorMessage: string | undefined;
 50→
 51→  if (!res.ok) {
 52→    try {
 53→      const parsed = JSON.parse(body);
 54→      errorMessage = parsed.message || parsed.error?.message;
 55→    } catch { /* ignore */ }
 56→  }
 57→
 58→  return { ok: res.ok, status: res.status, body, errorMessage };
 59→}
