  4→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  5→
  6→// No wildcard CORS — this is a server-to-server webhook endpoint.
  7→// Only allow OPTIONS for health checks with restrictive headers.
  8→const corsHeaders = {
  9→  "Access-Control-Allow-Origin": "",
 10→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 11→  "Access-Control-Allow-Headers": "content-type",
 12→};
