167→
168→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
169→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
170→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
171→
172→  // Helper to log and respond
173→  const logAndRespond = async (
174→    status: number,
175→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
176→    responseBody: Record<string, unknown>
177→  ) => {
178→    try {
179→      await supabase.from("email_ingest_logs").insert({
180→        sender: logData.sender || null,
181→        recipient: logData.recipient || null,
182→        user_id: logData.user_id || null,
183→        job_id: logData.job_id || null,
184→        status: logData.status,
185→        error_message: logData.error_message || null,
186→        attachments_count: logData.attachments_count || 0,
187→        resumes_created: logData.resumes_created || 0,
188→      });
189→    } catch (e) {
190→      console.error("Failed to log email ingest:", e);
191→      await logSystemError({
192→        function_name: "email-ingest",
193→        error_type: "INGEST_LOG_ERROR",
194→        severity: "warning",
195→        error_message: errorToMessage(e),
196→        error_stack: errorToStack(e),
197→        user_id: logData.user_id || null,
198→        job_id: logData.job_id || null,
199→      });
200→    }
201→    return new Response(JSON.stringify(responseBody), {
202→      status,
203→      headers: { ...corsHeaders, "Content-Type": "application/json" },
204→    });
205→  };
206→
207→  try {
208→    // Load platform config first — needed for webhook secret and settings
209→    const { data: config } = await supabase
210→      .from("platform_config")
211→      .select("email_ingestion_enabled, max_file_size_mb, max_resumes_per_job, resend_api_key, resend_inbound_webhook_secret")
212→      .limit(1)
213→      .single();
214→
215→    // --- [C1 FIX] Verify webhook signature before processing ---
216→    // Support both Svix (Resend) and HMAC verification
217→    const rawBodyText = await req.clone().text();
218→    const rawBody = new TextEncoder().encode(rawBodyText).buffer;
219→
220→    const hasSvixHeaders = req.headers.has("svix-id") && req.headers.has("svix-signature");
221→    let isValid = false;
222→
223→    if (hasSvixHeaders) {
224→      // Try DB-stored secret first, fallback to env var
225→      const svixSecret = (config as any)?.resend_inbound_webhook_secret || Deno.env.get("RESEND_INBOUND_WEBHOOK_SECRET");
226→      if (svixSecret) {
227→        isValid = verifySvixSignature(req, rawBodyText, svixSecret);
228→      }
229→    }
230→    if (!isValid) {
231→      isValid = await verifyWebhookSignature(req, rawBody);
232→    }
233→
234→    if (!isValid) {
235→      return await logAndRespond(
236→        401,
237→        { status: "rejected", error_message: "Invalid or missing webhook signature" },
238→        { error: "Unauthorized" }
239→      );
240→    }
241→
242→    // Check global email ingestion toggle
243→    if (config && !config.email_ingestion_enabled) {
244→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
245→    }
246→
247→    const maxFileSizeBytes = (config?.max_file_size_mb || 10) * 1024 * 1024;
248→    const maxResumesPerJob = config?.max_resumes_per_job || 50;
249→
250→    // Parse incoming payload — support structured JSON and multipart/form-data
251→    let sender: string | null = null;
252→    let recipient: string | null = null;
253→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
254→
255→    const contentType = req.headers.get("content-type") || "";
256→
257→    if (contentType.includes("application/json")) {
258→      const body = await req.json();
259→
260→      // Resend inbound webhook format (email.received event)
261→      if (body.type === "email.received" && body.data?.email_id) {
262→        const resendData = body.data;
263→        sender = resendData.from ? extractEmail(resendData.from) : null;
264→
265→        if (resendData.to && Array.isArray(resendData.to) && resendData.to.length > 0) {
266→          recipient = extractEmail(resendData.to[0]);
267→        }
268→
269→        // Resend webhooks only include attachment metadata — fetch content via API
270→        const resendApiKey = config?.resend_api_key;
271→        if (resendApiKey) {
272→          const fetched = await fetchResendAttachments(resendApiKey, resendData.email_id, maxFileSizeBytes);
273→          attachmentFiles.push(...fetched);
274→        } else {
275→          console.error("Resend API key not configured — cannot fetch attachments");
276→        }
277→      }
278→      // Structured JSON format (e.g. FromFull/ToFull/Attachments)
279→      else if (body.FromFull || body.ToFull || body.Attachments) {
280→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
281→
282→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
283→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
284→        } else if (body.To) {
285→          recipient = extractEmail(body.To);
286→        }
287→
288→        // Attachments: array of { Name, Content (base64), ContentType, ContentLength }
289→        if (body.Attachments && Array.isArray(body.Attachments)) {
290→          let count = 0;
291→          for (const att of body.Attachments) {
292→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
293→            if (!att.Name || !att.Content) continue;
294→            // [M2 FIX] Only accept PDF and DOCX
295→            if (!hasAllowedExtension(att.Name)) continue;
296→            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
297→            // [H2 FIX] Enforce file size limit
298→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
299→            attachmentFiles.push({ filename: att.Name, content: fileContent });
300→            count++;
301→          }
302→        }
303→      } else {
304→        // Legacy JSON format (backward compatible)
305→        sender = body.sender || null;
306→        recipient = body.recipient || null;
307→
308→        if (body.attachments && Array.isArray(body.attachments)) {
309→          let count = 0;
310→          for (const att of body.attachments) {
311→            if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
312→            if (!att.filename || !att.content) continue;
313→            // [M2 FIX] Enforce file type filter on legacy format too
314→            if (!hasAllowedExtension(att.filename)) continue;
315→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
316→            // [H2 FIX] Enforce file size limit
317→            if (fileContent.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
318→            attachmentFiles.push({ filename: att.filename, content: fileContent });
319→            count++;
320→          }
321→        }
322→      }
323→    } else if (contentType.includes("multipart/form-data")) {
324→      // Multipart form-data format (backward compatible)
325→      const formData = await req.formData();
326→
327→      const envelope = formData.get("envelope") as string | null;
328→      const fromField = formData.get("from") as string | null;
329→      const toField = formData.get("to") as string | null;
330→
331→      // Parse sender
332→      if (envelope) {
333→        try {
334→          const env = JSON.parse(envelope);
335→          if (env.from) sender = extractEmail(env.from);
336→        } catch { /* ignore */ }
337→      }
338→      if (!sender && fromField) sender = extractEmail(fromField);
339→
340→      // Parse recipient
341→      if (envelope) {
342→        try {
343→          const env = JSON.parse(envelope);
344→          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
345→        } catch { /* ignore */ }
346→      }
347→      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);
348→
349→      // [M1 FIX] Extract attachments with capped iteration count
350→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
351→      const maxIter = Math.min(Math.max(attachmentCount, 10), MAX_ATTACHMENTS_PER_EMAIL);
352→      let filesCollected = 0;
353→      for (let i = 1; i <= maxIter && filesCollected < MAX_ATTACHMENTS_PER_EMAIL; i++) {
354→        const file = formData.get(`attachment${i}`) as File | null;
355→        if (!file) continue;
356→        // [M2 FIX] Enforce file type filter on multipart format
357→        const filename = file.name || `attachment_${i}`;
358→        if (!hasAllowedExtension(filename)) continue;
359→        const buffer = await file.arrayBuffer();
360→        // [H2 FIX] Enforce file size limit
361→        if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
362→        attachmentFiles.push({
363→          filename,
364→          content: new Uint8Array(buffer),
365→        });
366→        filesCollected++;
367→      }
368→
369→      // Fallback: check for "attachment-info" pattern
370→      if (attachmentFiles.length === 0) {
371→        for (const [key, value] of formData.entries()) {
372→          if (filesCollected >= MAX_ATTACHMENTS_PER_EMAIL) break;
373→          if (key.startsWith("attachment") && value instanceof File) {
374→            const filename = value.name || key;
375→            // [M2 FIX] Enforce file type filter
376→            if (!hasAllowedExtension(filename)) continue;
377→            const buffer = await value.arrayBuffer();
378→            // [H2 FIX] Enforce file size limit
379→            if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
380→            attachmentFiles.push({
381→              filename,
382→              content: new Uint8Array(buffer),
383→            });
384→            filesCollected++;
385→          }
386→        }
387→      }
388→    } else {
389→      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
390→    }
391→
392→    if (!recipient) {
393→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
394→    }
395→
396→    // [L3 FIX] Validate recipient is a properly formatted email
397→    if (!isValidEmail(recipient)) {
398→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "Invalid recipient format" }, { error: "Invalid recipient" });
399→    }
400→
401→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
402→    let jobId: string | null = null;
403→    let userId: string | null = null;
404→
405→    const { data: jobMatch } = await supabase
406→      .from("jobs")
407→      .select("id, user_id")
408→      .eq("inbox_email", recipient)
409→      .single();
410→
411→    if (jobMatch) {
412→      jobId = jobMatch.id;
413→      userId = jobMatch.user_id;
414→    }
415→
416→    // Step 2: Fall back to user-level inbox routing
417→    if (!userId) {
418→      // Strip +tag for matching: abc+xyz@domain → abc@domain
419→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
420→
421→      // [C2 FIX] Use separate parameterized .eq() queries instead of .or() with string interpolation
422→      let profile: { user_id: string; credits: number; subscription_credits: number; topup_credits: number; bonus_credits: number; email_enabled: boolean; inbox_email: string } | null = null;
423→
424→      const { data: exactMatch } = await supabase
425→        .from("profiles")
426→        .select("user_id, credits, subscription_credits, topup_credits, bonus_credits, email_enabled, inbox_email")
427→        .eq("inbox_email", recipient)
428→        .limit(1)
429→        .single();
430→
431→      if (exactMatch) {
432→        profile = exactMatch;
433→      } else if (baseRecipient !== recipient) {
434→        const { data: baseMatch } = await supabase
435→          .from("profiles")
436→          .select("user_id, credits, subscription_credits, topup_credits, bonus_credits, email_enabled, inbox_email")
437→          .eq("inbox_email", baseRecipient)
438→          .limit(1)
439→          .single();
440→        profile = baseMatch;
441→      }
442→
443→      if (!profile) {
444→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
445→      }
446→
447→      userId = profile.user_id;
448→
449→      // Check per-user email toggle
450→      if (!profile.email_enabled) {
451→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
452→      }
453→
454→      // Check that user has credits before accepting resumes
455→      const splitTotal = (profile.subscription_credits || 0) + (profile.topup_credits || 0) + (profile.bonus_credits || 0);
456→      const totalCredits = splitTotal > 0 ? splitTotal : (profile.credits || 0);
457→      if (totalCredits <= 0) {
458→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: `Insufficient credits (have: ${totalCredits})` }, { error: "Insufficient credits" });
459→      }
460→    } else {
461→      // Verify the job owner has email enabled and has credits
462→      const { data: jobProfile } = await supabase
463→        .from("profiles")
464→        .select("email_enabled, credits, subscription_credits, topup_credits, bonus_credits")
465→        .eq("user_id", userId)
466→        .single();
467→
468→      if (jobProfile && !jobProfile.email_enabled) {
469→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
470→      }
471→
472→      // Check credits for job-routed emails too
473→      if (jobProfile) {
474→        const splitTotal = (jobProfile.subscription_credits || 0) + (jobProfile.topup_credits || 0) + (jobProfile.bonus_credits || 0);
475→        const totalCredits = splitTotal > 0 ? splitTotal : (jobProfile.credits || 0);
476→        if (totalCredits <= 0) {
477→          return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: `Insufficient credits (have: ${totalCredits})` }, { error: "Insufficient credits" });
478→        }
479→      }
480→    }
481→
482→    if (attachmentFiles.length === 0) {
483→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No valid attachments (only .pdf and .docx accepted)" }, { error: "No valid attachments" });
484→    }
485→
486→    // Find or create job if not already matched by per-job routing
487→    if (!jobId) {
488→      const { data: activeJob } = await supabase
489→        .from("jobs")
490→        .select("id")
491→        .eq("user_id", userId)
492→        .eq("status", "pending")
493→        .order("created_at", { ascending: false })
494→        .limit(1)
495→        .single();
496→
497→      if (activeJob) {
498→        jobId = activeJob.id;
499→      } else {
500→        // [M4 FIX] Rate-limit auto-created jobs: max 5 auto-created jobs per user per day
501→        const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
502→        const { count: recentAutoJobs } = await supabase
503→          .from("jobs")
504→          .select("id", { count: "exact", head: true })
505→          .eq("user_id", userId)
506→          .eq("job_description", "Auto-created from email ingestion")
507→          .gte("created_at", oneDayAgo);
508→
509→        if ((recentAutoJobs || 0) >= 5) {
510→          return await logAndRespond(429, { sender, recipient, user_id: userId, status: "rejected", error_message: "Too many auto-created jobs" }, { error: "Rate limit exceeded" });
511→        }
512→
513→        const { data: newJob } = await supabase
514→          .from("jobs")
515→          .insert({
516→            user_id: userId,
517→            job_description: "Auto-created from email ingestion",
518→            status: "pending",
519→          })
520→          .select("id")
521→          .single();
522→        if (!newJob) throw new Error("Failed to create job");
523→        jobId = newJob.id;
524→      }
525→    }
526→
527→    // [H3 FIX] Check existing resume count for the job before uploading
528→    const { count: existingResumeCount } = await supabase
529→      .from("resumes")
530→      .select("id", { count: "exact", head: true })
531→      .eq("job_id", jobId);
532→
533→    const remainingSlots = maxResumesPerJob - (existingResumeCount || 0);
534→    if (remainingSlots <= 0) {
535→      return await logAndRespond(429, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "Job has reached maximum resume limit" }, { error: "Resume limit reached for this job" });
536→    }
537→
538→    // Process attachments (limited to remaining slots)
539→    const resumeIds: string[] = [];
540→    const filesToProcess = attachmentFiles.slice(0, remainingSlots);
541→
542→    for (const att of filesToProcess) {
543→      // [M4 FIX] Sanitize filename to prevent path traversal or injection
544→      const safeName = sanitizeFilename(att.filename);
545→      const filePath = `${userId}/${jobId}/${Date.now()}_${safeName}`;
546→      await supabase.storage.from("resumes").upload(filePath, att.content);
547→
548→      const { data: resume } = await supabase
549→        .from("resumes")
550→        .insert({
551→          job_id: jobId,
552→          filename: safeName,
553→          file_path: filePath,
554→          source: "email",
555→        })
556→        .select("id")
557→        .single();
558→
559→      if (resume) resumeIds.push(resume.id);
560→    }
561→
562→    // Send confirmation email to the user (fire-and-forget)
563→    try {
564→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
565→      const userEmail = authUser?.user?.email;
566→
567→      if (userEmail) {
568→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
569→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
570→
571→        await supabase.functions.invoke("send-email", {
572→          body: {
573→            to: userEmail,
574→            template_key: "resume_received",
575→            variables: {
576→              user_name: userEmail.split("@")[0],
577→              job_title: jobTitle,
578→              attachment_count: String(filesToProcess.length),
579→              filename: filesToProcess.map((a) => a.filename).join(", "),
580→              job_id: jobId || "",
581→              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
582→            },
583→          },
584→        });
585→      }
586→    } catch (emailErr) {
587→      console.error("Failed to send resume received notification:", emailErr);
588→      await logSystemError({
589→        function_name: "email-ingest",
590→        error_type: "NOTIFICATION_SEND_ERROR",
591→        severity: "warning",
592→        error_message: errorToMessage(emailErr),
593→        error_stack: errorToStack(emailErr),
594→        user_id: userId,
595→        job_id: jobId,
596→      });
597→    }
598→
599→    return await logAndRespond(
600→      200,
601→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: filesToProcess.length, resumes_created: resumeIds.length },
602→      { success: true, resume_ids: resumeIds, job_id: jobId }
603→    );
604→  } catch (err: unknown) {
605→    console.error("email-ingest error:", err);
606→    await logSystemError({
607→      function_name: "email-ingest",
608→      error_type: "INGEST_ERROR",
609→      severity: "critical",
610→      error_message: errorToMessage(err),
611→      error_stack: errorToStack(err),
612→    });
613→    // [H4 FIX] Return generic error — never leak internal details
614→    return new Response(JSON.stringify({ error: "Internal server error" }), {
615→      status: 500,
616→      headers: { ...corsHeaders, "Content-Type": "application/json" },
617→    });
618→  }
619→});
