 11→export interface EmailOutreachDialogProps {
 12→  open: boolean;
 13→  onOpenChange: (open: boolean) => void;
 14→  candidateName: string;
 15→  candidateEmail: string;
 16→  jobTitle: string;
 17→  matchScore: number;
 18→  resumeId: string;
 19→  jobId: string;
 20→}
 21→
 22→function buildDefaultTemplate(candidateName: string, jobTitle: string, matchScore: number): string {
 23→  return `Hi ${candidateName},\n\nWe reviewed your application for the ${jobTitle} position and were impressed with your profile (${matchScore}% match).\n\nWe'd love to discuss this opportunity further. Would you be available for a brief call this week?\n\nBest regards`;
 24→}
 25→
 26→function buildDefaultSubject(jobTitle: string): string {
 27→  return `Regarding Your Application – ${jobTitle}`;
 28→}
 29→
 30→const EmailOutreachDialog = ({
 31→  open,
 32→  onOpenChange,
 33→  candidateName,
 34→  candidateEmail,
 35→  jobTitle,
 36→  matchScore,
 37→  resumeId,
 38→  jobId,
 39→}: EmailOutreachDialogProps) => {
 40→  const [subject, setSubject] = useState(() => buildDefaultSubject(jobTitle));
 41→  const [bodyText, setBodyText] = useState(() =>
 42→    buildDefaultTemplate(candidateName, jobTitle, matchScore)
 43→  );
 44→  const [isSending, setIsSending] = useState(false);
 45→
 46→  // Reset fields when the dialog opens with fresh values
 47→  const handleOpenChange = (nextOpen: boolean) => {
 48→    if (nextOpen) {
 49→      setSubject(buildDefaultSubject(jobTitle));
 50→      setBodyText(buildDefaultTemplate(candidateName, jobTitle, matchScore));
 51→    }
 52→    onOpenChange(nextOpen);
 53→  };
 54→
 55→  const bodyHtml = bodyText.replace(/\n/g, "<br>");
 56→
 57→  const handleSend = async () => {
 58→    if (!subject.trim()) {
 59→      toast.error("Please enter a subject");
 60→      return;
 61→    }
 62→    if (!bodyText.trim()) {
 63→      toast.error("Please enter a message body");
 64→      return;
 65→    }
 66→
 67→    setIsSending(true);
 68→    try {
 69→      const { data, error } = await supabase.functions.invoke("send-candidate-email", {
 70→        body: {
 71→          resume_id: resumeId,
 72→          job_id: jobId,
 73→          to_email: candidateEmail,
 74→          subject: subject.trim(),
 75→          body_html: bodyHtml,
 76→        },
 77→      });
 78→
 79→      if (error) throw error;
 80→
 81→      if (data?.skipped) {
 82→        toast.warning("Outbound email is currently disabled. Enable it in Admin > Email Settings.");
 83→        return;
 84→      }
 85→
 86→      if (data?.error) {
 87→        throw new Error(data.error);
 88→      }
 89→
 90→      toast.success(`Email sent to ${candidateName}`);
 91→      onOpenChange(false);
 92→    } catch (err: any) {
 93→      toast.error(err?.message || "Failed to send email");
 94→    } finally {
 95→      setIsSending(false);
 96→    }
