 26→async function adminCall(body: any) {
 27→  const { data: { session } } = await supabase.auth.getSession();
 28→  const res = await supabase.functions.invoke("admin-users", {
 29→    headers: { Authorization: `Bearer ${session?.access_token}` },
 30→    body,
 31→  });
 32→  if (res.error) throw new Error(res.error.message || "Admin call failed");
 33→  const data = res.data as any;
 34→  if (data?.error) throw new Error(data.error);
 35→  return data;
 36→}
