 70→// ─── Health Alert Banner ───
 71→function HealthBanner({ health, loading, onVerify }: {
 72→  health: ResendHealth | null;
 73→  loading: boolean;
 74→  onVerify: () => void;
 75→}) {
 76→  if (loading) {
 77→    return (
 78→      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
 79→        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
 80→        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
 81→      </div>
 82→    );
 83→  }
 84→
 85→  if (!health) return null;
 86→
 87→  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];
 88→
 89→  if (!health.keyValid) {
 90→    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
 91→  }
 92→  if (health.keyValid && !health.domainVerified) {
 93→    issues.push({
 94→      icon: AlertTriangle,
 95→      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
 96→      severity: "warning",
 97→    });
 98→  }
 99→
100→  if (issues.length === 0 && health.keyValid) {
101→    return (
102→      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
103→        <div className="flex items-center justify-between">
104→          <div className="flex items-center gap-2">
105→            <CheckCircle2 className="h-4 w-4 text-green-600" />
106→            <span className="text-sm font-medium text-green-700 dark:text-green-400">
107→              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
108→            </span>
109→          </div>
110→          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
111→            <RefreshCw className="h-3 w-3" /> Recheck
112→          </Button>
113→        </div>
114→        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
115→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
116→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
117→        </div>
118→      </div>
119→    );
120→  }
121→
122→  return (
123→    <div className="space-y-2">
124→      {issues.map((issue, i) => (
125→        <div
126→          key={i}
127→          className={`rounded-lg border p-3 flex items-start gap-2 ${
128→            issue.severity === "error"
129→              ? "border-destructive/50 bg-destructive/10 text-destructive"
130→              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
131→          }`}
132→        >
133→          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
134→          <p className="text-xs">{issue.text}</p>
135→        </div>
136→      ))}
137→      <div className="flex justify-end">
138→        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
139→          <RefreshCw className="h-3 w-3" /> Recheck
140→        </Button>
141→      </div>
142→    </div>
143→  );
144→}
